  var STAGES = [
    { k: 'devStartedAt', cls: 'st-dev',  name: 'dev started' },
    { k: 'prCreated',    cls: 'st-pr',   name: 'PR created' },
    { k: 'reviewedAt',   cls: 'st-rev',  name: 'reviewed' },
    { k: 'approvedAt',   cls: 'st-app',  name: 'approved' },
