    var h = ((prevCard && prevCard.history) || []).slice();
    if (terminalAt) {
        h.push({ state: key, at: terminalAt });
        return capHistory(h);
    }
    if (!hasPrev) {
        if (!h.length) h.push({ state: key });
        return capHistory(h);
    }
    if (prevKey !== key) h.push({ state: key, at: now });
    return capHistory(h);
}

