        if (!h.length) h.push({ state: key });
        return capHistory(h);
    }
    if (prevKey !== key) h.push({ state: key, at: now });
    return capHistory(h);
}

function capHistory(h) {
    return h.length > HISTORY_CAP ? h.slice(h.length - HISTORY_CAP) : h;
}

