  // js/factoryState.js LANE_ENTERED_AT — kept in sync deliberately)
  var LANE_ENTERED_AT = {
    development: 'devStartedAt',
    pr_created: 'prCreated',
    review: 'reviewedAt',
    approved_queue: 'approvedAt',
    validating: 'validatingAt',
